UPDATE trade_order SET status = #{status}, update_time = sysdate()
, ${timestamp} = sysdate()
WHERE order_id = #{orderId} AND status = 'unpaid' AND tenant_id = #{tenantId}

UPDATE trade_order SET status = #{toStatus}, update_time = NOW()
