UPDATE trade_order SET status = 'done', done_at = sysdate(), update_time = sysdate()
WHERE order_id = #{orderId} AND buyer_id = #{buyerId} AND status = 'shipped'
AND tenant_id = #{tenantId}

UPDATE trade_order SET status = 'closed', update_time = sysdate()
WHERE order_id = #{orderId} AND buyer_id = #{buyerId} AND status = 'unpaid'
AND tenant_id = #{tenantId}

